package mapdb

import (
	"context"
	"os"
	"path/filepath"
	"sort"
	"testing"

	"go.keploy.io/server/v3/pkg/models"
	"go.keploy.io/server/v3/pkg/platform/yaml"
	"go.keploy.io/server/v3/pkg/provenswitch"
	"go.uber.org/zap"
)

// writerFixtures are mappings files each writer rewrites: none, an empty
// one, keploy's own with and without its "# Generated by Keploy" line, and
// one a person edited (fields keploy does not know, comments, a shared: and
// a worker: section). Absent and empty files have no body to write.
var writerFixtures = map[string]string{
	"absent": "",
	"empty":  "\x00",
	"plain": `# Generated by Keploy (0.0.1)
version: api.keploy.io/v1beta1
kind: TestMocksMapping
test_set_id: s
tests:
    - id: o::TestA
      mock_entries:
        - name: mock-0
          kind: Http
`,
	"handedited": `# Generated by Keploy (0.0.1)
# Notes: TestB's mock-1 was moved back by hand.
version: api.keploy.io/v1beta1
kind: TestMocksMapping
test_set_id: s
reviewed_by: agent
tests:
    - id: o::TestA
      dir: o
      ticket: JIRA-123
      mock_entries:
        - name: mock-0
          kind: Http
          note: keep this one
    # TestB keeps its mock
    - id: o::TestB
      dir: o
      mock_entries:
        - name: mock-1
          kind: Http # inline
shared:
    - name: mock-7
      note: shared
worker:
    - name: mock-8
      kind: Http
      x: y
`,
	"nohead": `version: api.keploy.io/v1beta1
kind: TestMocksMapping
test_set_id: s
tests:
    - id: o::TestA
      mock_entries:
        - name: mock-0
          kind: Http
`,
}

// fileWriters are every writer of mappings.yaml, each with one write.
func fileWriters() map[string]func(*MappingDb) error {
	ctx := context.Background()
	return map[string]func(*MappingDb) error{
		"Insert": func(db *MappingDb) error {
			return db.Insert(ctx, &models.Mapping{TestSetID: "s", TestCases: []models.MappedTestCase{{ID: "o::TestC", Mocks: []models.MockEntry{{Name: "mock-2", Kind: "Http"}}}}})
		},
		"Upsert": func(db *MappingDb) error {
			return db.Upsert(ctx, "s", "o::TestC", []models.MockEntry{{Name: "mock-2", Kind: "Http"}})
		},
		"UpsertBatch": func(db *MappingDb) error {
			return db.UpsertBatch(ctx, "s", map[string][]models.MockEntry{"o::TestC": {{Name: "mock-2", Kind: "Http"}}})
		},
		"UpsertWorker": func(db *MappingDb) error {
			return db.UpsertWorker(ctx, "s", []models.MockEntry{{Name: "mock-8", Kind: "Http"}})
		},
		"MoveToWorker": func(db *MappingDb) error {
			_, err := db.MoveToWorker(ctx, "s", []models.MockEntry{{Name: "mock-0", Kind: "Http"}})
			return err
		},
		"MarkRecordedWith": func(db *MappingDb) error {
			return db.MarkRecordedWith(ctx, "s", "probe-feature")
		},
		"UpsertBoots": func(db *MappingDb) error {
			return db.UpsertBoots(ctx, "s", []models.BootSpec{{Dir: "o", Key: "k", Program: "p"}})
		},
		"UpsertCases": func(db *MappingDb) error {
			return db.UpsertCases(ctx, "s", map[string]models.MappedTestCase{"o::TestA": {ID: "o::TestA", Cases: []string{"test-1"}}}, nil, nil)
		},
		"UpsertConcurrency": func(db *MappingDb) error {
			return db.UpsertConcurrency(ctx, "s", []models.ConcurrencyGroup{{ID: "g", Tests: []string{"o::TestA"}}}, []models.MockEntry{{Name: "mock-7"}})
		},
	}
}

// Without the proven switch every writer writes, over each fixture, byte
// for byte the file keploy wrote before it kept hand edits: what a hand edit
// added and the comments are dropped, and keploy's line is where each writer
// always put it (on every write, on a file it creates, or never). The
// goldens were written by main before this change. A file whose entries use
// a YAML merge key (<<) is not among them: keploy reads what the merge key
// brings now, a declared fix
// (models.TestAMergeKeyGivesATestEntryItsMocks).
func TestEachWriterWritesAsBeforeWithoutTheSwitch(t *testing.T) {
	t.Setenv(provenswitch.Env, "")
	writers := fileWriters()
	names := make([]string, 0, len(writers))
	for name := range writers {
		names = append(names, name)
	}
	sort.Strings(names)
	for fixture, body := range writerFixtures {
		t.Run(fixture, func(t *testing.T) {
			var got []byte
			for _, name := range names {
				dir := t.TempDir()
				must(t, os.MkdirAll(filepath.Join(dir, "s"), 0o755))
				if body != "" {
					file := []byte(body)
					if body == "\x00" {
						file = nil
					}
					must(t, os.WriteFile(filepath.Join(dir, "s", "mappings.yaml"), file, 0o644))
				}
				got = append(got, "### "+name+"\n"...)
				if err := writers[name](NewWithFormat(zap.NewNop(), dir, "mappings", yaml.FormatYAML)); err != nil {
					got = append(got, "ERR: "+err.Error()+"\n"...)
				}
				if written, err := os.ReadFile(filepath.Join(dir, "s", "mappings.yaml")); err == nil {
					got = append(got, written...)
				} else {
					got = append(got, "NOFILE\n"...)
				}
			}
			checkSwitchOffGolden(t, "writers-"+fixture+".golden", got)
		})
	}
}
